    ON public.landmark_place_aliases FOR ALL TO zentrip_api_runtime
    USING (TRUE) WITH CHECK (TRUE);
DROP POLICY IF EXISTS zentrip_landmark_search_areas_runtime ON public.landmark_search_areas;
